// Cine de Cali: cartelera del mes, horarios en Cine Colombia, Cinépolis y Cinemark, y si la película vale la pena.
// La IA busca en la web (herramienta de búsqueda de Anthropic) y lo que encuentra se guarda un rato para no gastar de más.
// cartelera → películas del mes · horarios → funciones de una película en los 3 cines · opinion → ¿vale la pena? · clave → clave gratis de TMDB (opcional, para pósters)
const it = $input.first().json;
let b = it.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
if (b.token !== 'mercado-7d41c2a9e05b') return [{ json: { listo: true, respuesta: { ok: false, error: 'token' } } }];
const MODELO = 'claude-haiku-4-5-20251001';
const sd = $getWorkflowStaticData('global');
sd.cache = sd.cache || {};
const accion = ['cartelera', 'horarios', 'opinion', 'clave'].includes(b.accion) ? b.accion : 'cartelera';
const co = new Date(Date.now() - 5 * 3600 * 1000);
const hoy = co.toISOString().slice(0, 10);
const limpia = (t) => String(t || '').replace(/[<>{}\[\]\n\r"]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 90);

if (accion === 'clave') {
  const k = String(b.clave || '').trim();
  sd.tmdb = /^[A-Za-z0-9]{16,64}$/.test(k) ? k : '';
  Object.keys(sd.cache).filter(x => x.startsWith('cartelera')).forEach(x => delete sd.cache[x]);
  return [{ json: { listo: true, respuesta: { ok: true, conClave: !!sd.tmdb } } }];
}

const titulo = limpia(b.titulo);
const fecha = /^\d{4}-\d{2}-\d{2}$/.test(String(b.fecha || '')) ? b.fecha : hoy;
if ((accion === 'horarios' || accion === 'opinion') && !titulo) return [{ json: { listo: true, respuesta: { ok: false, error: 'titulo' } } }];

const TTL = { cartelera: 12, horarios: 2, opinion: 24 };
const mes = hoy.slice(0, 7);
const clave = accion === 'cartelera' ? 'cartelera|' + mes : accion === 'horarios' ? 'horarios|' + titulo.toLowerCase() + '|' + fecha : 'opinion|' + titulo.toLowerCase();
const c = sd.cache[clave];
if (c && !b.forzar && Date.now() - c.t < TTL[accion] * 3600 * 1000) return [{ json: { listo: true, respuesta: Object.assign({}, c.v, { enCache: true }) } }];

const PERFIL = 'La familia son una pareja adulta con un hijo pequeño (Ema) en Cali. Les gusta el suspenso y los thrillers bien hechos (como «Perdida»), la acción si de verdad es buena, y las películas con buena crítica. No les gusta el terror ni el anime violento (como «Demon Slayer»).';
const SISTEMA = 'Eres Armoni, el asistente de una familia de Cali (Colombia). Usa la búsqueda web para dar datos actuales y reales; nunca inventes películas, horarios ni puntajes: si no encuentras algo, déjalo vacío o en null. Responde SOLO con un JSON válido, sin texto adicional ni comillas dobles dentro de los textos.';
let prompt = '';
if (accion === 'cartelera') {
  prompt = 'Hoy es ' + hoy + '. Busca la cartelera ACTUAL de los cines de Cali, Colombia (Cine Colombia, Cinépolis y Cinemark) y arma la lista de películas que están en cartelera este mes (máximo 14). ' + PERFIL +
    ' Para cada película da: titulo (como se anuncia en Colombia), original (título original), generos (lista corta en español), duracion (minutos o null), clasificacion (edad en Colombia o null), sinopsis (una frase corta), score (puntaje de críticos de 0 a 100 de Rotten Tomatoes, Metacritic o IMDb convertido, o null), fuente (de dónde sale el puntaje), estreno (AAAA-MM-DD o null), encaja ("si", "tal vez" o "no" según el perfil de la familia) y porque (una frase corta del porqué encaja o no). ' +
    'Formato: {"peliculas":[{"titulo":"","original":"","generos":[],"duracion":null,"clasificacion":null,"sinopsis":"","score":null,"fuente":"","estreno":null,"encaja":"tal vez","porque":""}]}';
} else if (accion === 'horarios') {
  prompt = 'Busca las funciones de la película «' + titulo + '» en Cali, Colombia, para el día ' + fecha + ', en estos tres cines: Cine Colombia, Cinépolis y Cinemark. Para cada cine lista sus sedes en Cali que la pasan y los horarios con formato (2D, 3D, 4DX, VIP, etc.) e idioma (Doblada o Subtitulada). Si un cine no la pasa ese día, déjalo con sedes vacías. Incluye en "url" la página del cine donde se ven las funciones. ' +
    'Formato: {"cines":[{"cine":"Cine Colombia","url":"","sedes":[{"sede":"","horarios":[{"hora":"18:30","formato":"2D","idioma":"Subtitulada"}]}]},{"cine":"Cinépolis","url":"","sedes":[]},{"cine":"Cinemark","url":"","sedes":[]}],"nota":""}';
} else {
  prompt = 'Hoy es ' + hoy + '. Dime si vale la pena ir a ver al cine «' + titulo + '». Busca reseñas de críticos, el puntaje del público y lo que se dice en redes y medios. ' + PERFIL +
    ' Distingue el ruido de la calidad: una película de la que se habla mucho solo vale la pena si además las críticas o el público la respaldan, o si superó las expectativas. Veredicto: "vale" solo si hay conversación fuerte Y la calidad lo respalda (o superó expectativas); "esperar" si hay mucho ruido pero la calidad es dudosa o aún no hay reseñas suficientes; "no" si las críticas son malas o no encaja con la familia. ' +
    'Formato: {"veredicto":"esperar","titular":"frase corta","resumen":"dos frases","razones":["","",""],"critica":{"score":null,"fuente":""},"publico":{"score":null,"fuente":""},"buzz":"alto|medio|bajo","superoExpectativas":false}';
}
// sin user_location: la búsqueda de Anthropic no acepta Colombia como país; el lugar va en la pregunta
const peticion = { model: MODELO, max_tokens: 4000, system: SISTEMA,
  tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: accion === 'cartelera' ? 6 : 5 }],
  messages: [{ role: 'user', content: prompt }] };
return [{ json: { listo: false, accion, clave, titulo, fecha, peticion } }];

// Lee lo que encontró la IA, lo limpia, le pone póster y puntaje de TMDB si hay clave, y lo guarda un rato.
const http = (o) => this.helpers.httpRequest(o);
const v = $('Validar').first().json;
const sd = $getWorkflowStaticData('global');
sd.cache = sd.cache || {};
const r = $input.first().json;
const texto = (Array.isArray(r.content) ? r.content : []).filter(x => x.type === 'text').map(x => x.text).join('\n');
const m = texto.match(/\{[\s\S]*\}/);
let out = null;
try { out = JSON.parse(m ? m[0] : texto); } catch (e) {}
if (!out) return [{ json: { respuesta: { ok: false, error: 'ia' } } }];
const txt = (t, n) => String(t == null ? '' : t).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n || 200);
const num = (x) => { const n = Number(x); return isFinite(n) && x !== null && x !== '' ? Math.max(0, Math.min(100, Math.round(n))) : null; };
const slug = (t) => String(t).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
let respuesta;

if (v.accion === 'cartelera') {
  let pelis = (Array.isArray(out.peliculas) ? out.peliculas : []).slice(0, 16).map(p => ({
    id: slug(txt(p.titulo, 90)), titulo: txt(p.titulo, 90), original: txt(p.original, 90), generos: (Array.isArray(p.generos) ? p.generos : []).slice(0, 3).map(g => txt(g, 24)),
    duracion: Number(p.duracion) > 0 ? Math.round(Number(p.duracion)) : null, clasificacion: txt(p.clasificacion, 12) || null, sinopsis: txt(p.sinopsis, 220),
    score: num(p.score), fuente: txt(p.fuente, 30), estreno: /^\d{4}-\d{2}-\d{2}$/.test(String(p.estreno || '')) ? p.estreno : null,
    encaja: ['si', 'tal vez', 'no'].includes(p.encaja) ? p.encaja : 'tal vez', porque: txt(p.porque, 140), poster: null
  })).filter(p => p.titulo);
  if (sd.tmdb) {
    await Promise.all(pelis.map(async (p) => {
      try {
        const q = encodeURIComponent(p.original || p.titulo);
        const res = await http({ method: 'GET', url: 'https://api.themoviedb.org/3/search/movie?api_key=' + sd.tmdb + '&language=es-CO&query=' + q, json: true, timeout: 10000 });
        const f = res && res.results && res.results[0];
        if (f) { if (f.poster_path) p.poster = 'https://image.tmdb.org/t/p/w342' + f.poster_path; if (p.score == null && f.vote_average > 0) { p.score = Math.round(f.vote_average * 10); p.fuente = 'TMDB'; } }
      } catch (e) {}
    }));
  }
  pelis.sort((a, b) => (b.score == null ? -1 : b.score) - (a.score == null ? -1 : a.score));
  respuesta = { ok: true, peliculas: pelis, conClave: !!sd.tmdb, actualizado: new Date().toISOString() };
} else if (v.accion === 'horarios') {
  const CINES = ['Cine Colombia', 'Cinépolis', 'Cinemark'];
  const cines = CINES.map(nombre => {
    const c = (Array.isArray(out.cines) ? out.cines : []).find(x => String(x.cine || '').toLowerCase().replace(/[^a-z]/g, '').startsWith(nombre.toLowerCase().normalize('NFD').replace(/[^a-z]/g, '').slice(0, 6))) || {};
    const sedes = (Array.isArray(c.sedes) ? c.sedes : []).slice(0, 8).map(s => ({ sede: txt(s.sede, 50), horarios: (Array.isArray(s.horarios) ? s.horarios : []).filter(h => /^\d{1,2}:\d{2}$/.test(String(h.hora || ''))).slice(0, 12).map(h => ({ hora: String(h.hora).padStart(5, '0'), formato: txt(h.formato, 12), idioma: txt(h.idioma, 14) })) })).filter(s => s.sede && s.horarios.length);
    const url = /^https:\/\//.test(String(c.url || '')) ? String(c.url).slice(0, 200) : '';
    return { cine: nombre, url, sedes };
  });
  respuesta = { ok: true, titulo: v.titulo, fecha: v.fecha, cines, nota: txt(out.nota, 160), actualizado: new Date().toISOString() };
} else {
  const sc = (o) => ({ score: num(o && o.score), fuente: txt(o && o.fuente, 30) });
  respuesta = { ok: true, titulo: v.titulo, veredicto: ['vale', 'esperar', 'no'].includes(out.veredicto) ? out.veredicto : 'esperar', titular: txt(out.titular, 120), resumen: txt(out.resumen, 320),
    razones: (Array.isArray(out.razones) ? out.razones : []).slice(0, 3).map(x => txt(x, 140)).filter(Boolean), critica: sc(out.critica), publico: sc(out.publico),
    buzz: ['alto', 'medio', 'bajo'].includes(out.buzz) ? out.buzz : 'medio', superoExpectativas: !!out.superoExpectativas, actualizado: new Date().toISOString() };
}
sd.cache[v.clave] = { t: Date.now(), v: respuesta };
const ks = Object.keys(sd.cache);
if (ks.length > 80) ks.sort((a, b) => sd.cache[a].t - sd.cache[b].t).slice(0, ks.length - 80).forEach(k => delete sd.cache[k]);
return [{ json: { respuesta } }];
